"""Package actual Kotlin WAVs, source and evidence for the first TRIAD listen."""
from pathlib import Path
import csv, json, shutil, hashlib, zipfile, sys, subprocess
repo=Path(__file__).resolve().parents[1]
src=repo/'testkit/triad-audition'
out=Path(sys.argv[1] if len(sys.argv)>1 else '/workspace/sites/triad-audition/dist')
out.mkdir(parents=True,exist_ok=True)
for f in src.glob('*'):
    if f.is_file(): shutil.copy2(f,out/f.name)
files=['synth/src/main/kotlin/com/snipsnap/synth/Triad.kt','synth/src/test/kotlin/com/snipsnap/synth/TriadAuditionGenerator.kt','synth/src/test/kotlin/com/snipsnap/synth/TriadTest.kt','docs/TRIAD.md']
for f in files: shutil.copy2(repo/f,out/Path(f).name)
metrics=list(csv.DictReader((src/'metrics.csv').open()))
assert len(metrics)==22
assert all(float(r['peak'])<2 for r in metrics), 'Native PCM would clip; increase the fixed native transport headroom before publishing'
manifest={'baseline':'c00edb997','renderer':'native Kotlin','settings':json.loads((src/'settings.json').read_text()),'files':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in out.glob('*') if p.suffix in ('.wav','.kt','.md','.csv','.json') and p.name != 'manifest.json'}}
(out/'manifest.json').write_text(json.dumps(manifest,indent=2))
for archive,native in [('triad-audition.zip',False),('triad-native.zip',True)]:
    with zipfile.ZipFile(out/archive,'w',zipfile.ZIP_DEFLATED) as z:
        for p in out.iterdir():
            if p.suffix in ('.kt','.md','.csv','.json') or (p.suffix=='.wav' and ('-native' in p.stem)==native): z.write(p,p.name)
css='''*{box-sizing:border-box}body{margin:0;background:#111414;color:#eeeae2;font:16px/1.55 system-ui,sans-serif}main{max-width:1150px;margin:auto;padding:54px 28px}a{color:#d9ee8e}header{padding-bottom:44px;border-bottom:1px solid #46504a}.eyebrow{font:12px ui-monospace,monospace;letter-spacing:.17em;color:#b7c3ba;text-transform:uppercase}h1{font-size:clamp(58px,10vw,112px);line-height:.95;letter-spacing:-.07em;margin:26px 0}h1 span{color:#d9ee8e}h2{font-size:30px;letter-spacing:-.035em;margin:0 0 12px}h3{font-size:22px;margin:8px 0}.lead{max-width:680px;font-size:21px;color:#c5cbc5}.badge{display:inline-block;padding:6px 10px;border:1px solid #546054;border-radius:30px;font:12px ui-monospace,monospace;margin:0 8px 10px 0}.actions{display:flex;gap:20px;align-items:center;flex-wrap:wrap}.download{display:inline-block;background:#d9ee8e;color:#172015;padding:12px 18px;border-radius:5px;text-decoration:none;font-weight:650}section{padding:36px 0;border-bottom:1px solid #46504a}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{padding:22px;background:#1d2420;border:1px solid #38463b;border-radius:8px}.card:nth-child(2){background:#1b272b}.card:nth-child(3){background:#29212c}.number{font:13px ui-monospace,monospace;color:#d9ee8e}.hint,small{color:#b2bcb4;font-size:14px}.controls{display:flex;gap:7px;flex-wrap:wrap;margin:20px 0}button,select{font:inherit;color:#eee;background:#29342c;border:1px solid #61705e;padding:8px 12px;border-radius:5px;cursor:pointer}button[aria-pressed=true]{background:#d9ee8e;color:#172015}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #e6b6ff;outline-offset:3px}audio{width:100%;margin:8px 0}label{display:block;font-size:13px;color:#c5cbc5}.stems{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.stem{padding:14px;background:#1b211e;border-radius:6px}details{margin-top:16px}summary{cursor:pointer;color:#d9ee8e}.flow{font:13px ui-monospace,monospace;color:#c5cbc5;min-height:44px}footer{padding:30px 0;color:#b2bcb4;font-size:14px}@media(max-width:760px){main{padding:30px 18px}.grid,.stems{grid-template-columns:1fr}h1{font-size:72px}.lead{font-size:18px}}'''
rigs=[('warehouse','Warehouse Slam','Clamp → drive','Listen for the kick pulling the whole percussion bed down, then releasing it. Does the thud survive the crunch?'),('submerged','Submerged','Shape → tape','Listen for hats and hand drums in the repeats. Does the low end stay anchored underneath the haze?'),('fracture','Glitch & Morph','Crush → grains','Listen for reversed and pitched fragments answering the beat. Is it evolving, or losing the groove?')]
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="One hybrid drum groove. Three shared-bus rigs. A SnipSnap listening test."><title>TRIAD · Three drum rigs</title><style>'''+css+'''</style></head><body><main><header><p class="eyebrow">SnipSnap / listening room / study 01</p><h1>One groove.<br><span>Three lives.</span></h1><p class="lead">Sub weight, a hard thud and swinging hand percussion. Choose what happens when they hit the same bus.</p><div><span class="badge">124 BPM</span><span class="badge">4 BARS + TAIL</span><span class="badge">MONO · 44.1 kHz</span></div><div class="actions"><a class="download" href="triad-audition.zip" download>Download WAVs + source ↓</a><a href="#compare">Start the comparison</a></div><p class="hint">First native Kotlin audition. These are listening candidates. Start at a comfortable volume; the page plays one track at a time.</p></header><section id="compare"><h2>First, meet the dry groove.</h2><p>Every rig below receives this exact performance. A 3-second tail follows the four bars. The files are finite phrases, not seamless loops.</p><label for="dry">Unprocessed shared mix · matched listening level</label><audio id="dry" controls preload="none" src="dry.wav"></audio><p class="hint">Full mixes and first-stage comparisons are matched down to one achievable whole-performance loudness level. Solo stems are raised separately. Native exports share a fixed −6.02 dB transport gain to preserve headroom. <a href="triad-native.zip" download>Download the native levels separately</a>.</p></section><section><h2>Pick a direction.</h2><p>Start with Main, then compare Light and Heavy. Switching amount keeps your place when playback is already running.</p><div class="grid">'''
for n,title,flow,question in rigs:
    html+=f'''<article class="card" data-rig="{n}"><span class="number">0{rigs.index((n,title,flow,question))+1}</span><h3>{title}</h3><p class="flow">{flow}</p><p>{question}</p><div class="controls" role="group" aria-label="{title} intensity">'''
    for level in ['light','main','heavy']:
        html+=f'<button type="button" data-level="{level}" aria-pressed="{str(level=="main").lower()}">{level.title()}</button>'
    html+=f'''</div><label for="{n}">{title} · <span class="amount">Main</span></label><audio id="{n}" controls preload="none" src="{n}-main.wav"></audio><details><summary>Hear stage one alone</summary><p class="hint">Same loudness target. Compare the first processor with the complete chain above.</p><audio controls preload="none" aria-label="{title} first stage" src="{n}-first.wav"></audio></details></article>'''
html+='''</div></section><section><h2>Pull the source apart.</h2><p>Check the character before the pedals. Stems are raised to the listening target for inspection; these solo levels are not their balance in the mix.</p><div class="stems">'''
for n in ['thud','sub','clap','open-hat','closed-hat','shaker','conga','bongo','rim']:
    html+=f'<div class="stem"><label for="stem-{n}">{n.replace("-"," ").title()}</label><audio id="stem-{n}" controls preload="none" src="stem-{n}.wav"></audio></div>'
html+='''</div></section><section><h2>What to listen for</h2><p>Tell me which rig and amount you prefer, whether the dry hand drums have enough character, and whether the kick still has enough punch. “Warehouse Main, more shaker, shorter sub” is enough to guide the next pass.</p><details><summary>Why it is built this way</summary><p>One shared bus makes the drums affect each other. One source performance makes the comparison fair. A bass-reduced tape send keeps echoes above the low-end anchor. Windowed grains soften edit boundaries, while the full-band fracture path tests how far the low end can be pushed.</p><p>These are mechanism-inspired adaptations, not hardware emulations. The hand drums are synthesized membranes, not samples of the original machines. No listening verdict is claimed.</p><p><a href="TRIAD.md">Design and research notes</a> · <a href="metrics.csv">Measured levels and render times</a> · <a href="matching.csv">Final level matching</a> · <a href="events.csv">Exact rhythm</a> · <a href="manifest.json">Reproduction manifest</a></p></details></section><footer>TRIAD · SnipSnap · Study 01<br>Native Kotlin source, generated audio and measurements included. Phone integration, an MPC program and seamless HOLD are outside this first listening gate.</footer></main><script>
document.addEventListener('play', e=>{if(e.target.tagName==='AUDIO')document.querySelectorAll('audio').forEach(a=>{if(a!==e.target)a.pause()})},true);
document.querySelectorAll('[data-level]').forEach(b=>b.addEventListener('click',()=>{const card=b.closest('[data-rig]'),a=card.querySelector('audio'),playing=!a.paused,t=a.currentTime;card.querySelectorAll('[data-level]').forEach(k=>k.setAttribute('aria-pressed',String(k===b)));card.querySelector('.amount').textContent=b.textContent;a.src=card.dataset.rig+'-'+b.dataset.level+'.wav';a.addEventListener('loadedmetadata',()=>{a.currentTime=Math.min(t,a.duration||0);if(playing)a.play().catch(()=>{})},{once:true});a.load()}));
</script></body></html>'''
(out/'index.html').write_text(html)
# Static QA: all asset links exist and delivered WAV payloads match renderer files.
import re
for link in re.findall(r'(?:src|href)="([^"]+)"',html):
    if not link.startswith(('#','http')): assert (out/link).is_file(),link
for f in src.glob('*.wav'): assert f.read_bytes()==(out/f.name).read_bytes()
print(f'Packaged {len(metrics)} comparisons and {len(list(out.glob("*.wav")))} WAVs; all links and PCM copies verified.')
